style.css:
@-moz-document domain("roblox.com") {
/* ===== Blue Hour Palette ===== */
  :root {
    --bh-bg:        #0a1024;
    --bh-bg-2:      #0f1730;
    --bh-surface:   #141d3a;
    --bh-raised:    #1b2650;
    --bh-border:    #263463;
    --bh-accent:    #7aa2ff;
    --bh-accent-2:  #a99bff;
    --bh-text:      #d3dcf5;
    --bh-muted:     #8a98c2;
    --bh-glow:      rgba(122, 162, 255, .25);
  }

  /* ===== พื้นหลังหลัก + แสงแอมเบียนต์ ===== */
  html, body, body.rbx-body, #wrap, .wrap {
    background:
      radial-gradient(1200px 600px at 15% -10%, rgba(122,162,255,.14), transparent 60%),
      radial-gradient(900px 500px at 100% 0%, rgba(169,155,255,.10), transparent 60%),
      linear-gradient(180deg, var(--bh-bg) 0%, var(--bh-bg-2) 100%) fixed !important;
    color: var(--bh-text) !important;
  }

  .container-main, .content, #container-main, #content {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* ===== แถบนำทางด้านบน ===== */
  #header, .rbx-header, .navbar-fixed-top {
    background: rgba(12, 19, 44, .88) !important;
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--bh-border) !important;
    box-shadow: 0 2px 20px rgba(0,0,0,.35) !important;
  }
  .nav-menu-title, .font-header-2, .navbar .text-header { color: var(--bh-text) !important; }
  .nav-menu-title:hover { color: var(--bh-accent) !important; }

  /* ===== เมนูซ้าย (แบบเก่า) ===== */
  #left-navigation-container, .rbx-left-col, .left-col-list {
    background: #0a1024 !important;
    border-right: 1px solid #141d3a !important;
  }
  .left-col-list a, .left-col-list .font-header-2 { color: var(--bh-text) !important; }
  .left-col-list li:hover, .left-col-list a:hover {
    background: var(--bh-raised) !important;
    color: var(--bh-accent) !important;
  }

  /* ===== ข้อความ ===== */
  h1, h2, h3, h4, h5, h6,
  .text-header, .text-lead, .text-label, .text-body, .font-header-1,
  .container-header h2, .game-card-name, .item-card-name {
    color: var(--bh-text) !important;
  }
  .text-secondary, .text-footer, .text-muted, .game-card-info, .text-description {
    color: var(--bh-muted) !important;
  }
  a, a.text-link { color: var(--bh-accent) !important; }
  a:hover, a.text-link:hover { color: var(--bh-accent-2) !important; }

  /* ===== การ์ด / กล่องเนื้อหา (โปร่งใส) ===== */
  .section, .section-content, .content-background, .game-card-container,
  .item-card-container, .card, .rbx-tab-content, .profile-container,
  .list-item, .game-card-link {
    background: transparent !important;
    background-color: transparent !important;
    border-color: var(--bh-border) !important;
    color: var(--bh-text) !important;
  }
  .game-card-container:hover, .item-card-container:hover {
    box-shadow: 0 0 22px var(--bh-glow) !important;
    transform: translateY(-2px);
    transition: .2s ease;
  }
  .game-card-thumb-container, .thumbnail-2d-container, .game-card-thumb {
    border-radius: 10px !important;
  }

  /* ===== ทำให้กล่องอื่นๆ โปร่งใส ===== */
  .info-container,
  .info-metadata-container,
  .wide-game-tile-metadata,
  .base-metadata,
  .hover-metadata,
  .game-card-info,
  .game-tile,
  .game-container,
  .game-carousel,
  .game-sort-carousel-wrapper,
  .container-header,
  .container-list,
  .home-container,
  #HomeContainer,
  .friend-carousel-container,
  .friends-carousel-container,
  .section-content-off,
  [class*="home-"],
  [class*="game-sort"],
  [class*="friend-"] {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important;
  }

  /* หัวข้อ "Home" ด้านบน */
  .content > div:first-child,
  #content > div:first-child,
  #place-list > div:first-child,
  .home-header,
  [class*="home-header"],
  h1, h1 * {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* ตัวแปรสีพื้นผิวของ Foundation UI (ทำให้กล่องที่ใช้ตัวแปรโปร่งใส) */
  :root, body {
    --color-surface-100: transparent !important;
    --color-surface-200: transparent !important;
    --color-surface-300: transparent !important;
  }

  /* ===== ปุ่ม ===== */
  .btn-primary-md, .btn-primary-lg, .btn-primary-sm, .btn-common-play-game-lg {
    background: linear-gradient(135deg, #4f78e6, #7b6cf0) !important;
    border: none !important;
    color: #fff !important;
    box-shadow: 0 0 14px var(--bh-glow) !important;
  }
  .btn-primary-md:hover, .btn-common-play-game-lg:hover { filter: brightness(1.15); }

  .btn-secondary-md, .btn-secondary-lg, .btn-control-md, .btn-control-sm,
  .btn-control-lg, .btn-generic-more-sm {
    background: var(--bh-raised) !important;
    border: 1px solid var(--bh-border) !important;
    color: var(--bh-text) !important;
  }
  .btn-secondary-md:hover, .btn-control-md:hover {
    border-color: var(--bh-accent) !important;
    color: var(--bh-accent) !important;
  }

  /* ===== ช่องกรอก / ค้นหา ===== */
  input, textarea, select, .form-control, .input-field, .navbar-search input {
    background: var(--bh-bg-2) !important;
    border: 1px solid var(--bh-border) !important;
    color: var(--bh-text) !important;
  }
  input:focus, textarea:focus, .form-control:focus {
    border-color: var(--bh-accent) !important;
    box-shadow: 0 0 0 3px var(--bh-glow) !important;
    outline: none !important;
  }
  ::placeholder { color: var(--bh-muted) !important; }

  /* ===== เมนูดรอปดาวน์ / โมดัล / Popover ===== */
  .dropdown-menu, .popover, .modal-content, .modal-dialog .modal-content,
  .notification-stream-popover, .foundation-web-menu {
    background: var(--bh-surface) !important;
    border: 1px solid var(--bh-border) !important;
    color: var(--bh-text) !important;
    box-shadow: 0 10px 40px rgba(0,0,0,.5) !important;
  }
  .dropdown-menu li a:hover { background: var(--bh-raised) !important; }
  .modal-backdrop { background: #02050f !important; }

  /* ===== แชต ===== */
  #chat-container, .chat-main, .chat-container, .dialogue-container {
    background: var(--bh-surface) !important;
    border-color: var(--bh-border) !important;
    color: var(--bh-text) !important;
  }

  /* ===== ฟุตเตอร์ ===== */
  footer, .container-footer, .footer {
    background: var(--bh-bg) !important;
    border-top: 1px solid var(--bh-border) !important;
  }
  .footer-link, .footer a, .text-footer { color: var(--bh-muted) !important; }
  .footer a:hover { color: var(--bh-accent) !important; }

  /* ===== แถบเลื่อน ===== */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: var(--bh-bg); }
  ::-webkit-scrollbar-thumb { background: var(--bh-raised); border-radius: 8px; }
  ::-webkit-scrollbar-thumb:hover { background: var(--bh-accent); }

  /* ===== แถบซ้าย (Foundation UI) ===== */
  .left-nav,
  .left-nav > div,
  .left-nav .bg-surface-0,
  .left-nav nav {
    background: #060a18 !important;
    background-color: #060a18 !important;
  }

  .left-nav [role="separator"] {
    border-left-color: #141d3a !important;
  }

  .left-nav a,
  .left-nav button,
  .left-nav .content-emphasis,
  .left-nav .text-title-large {
    color: var(--bh-text) !important;
  }
  .left-nav .icon {
    color: var(--bh-accent) !important;
  }

  .left-nav a:hover,
  .left-nav button:hover {
    background: #0f1730 !important;
  }
  .left-nav a:hover .icon,
  .left-nav a:hover span {
    color: var(--bh-accent-2) !important;
  }

  .left-nav .bg-shift-200 {
    background: #141d3a !important;
  }

  /* ===== หัวข้อ section (Recommended For You, Continue ฯลฯ) ===== */
  .game-sort-header-container *,
  .container-header *,
  .sort-header *,
  [class*="sort-header"] *,
  [class*="SortHeader"] *,
  [data-testid*="sort"] h2,
  [data-testid*="sort"] a,
  h2, h2 a, h2 span,
  .content-emphasis,
  .text-heading-medium,
  .text-heading-large,
  .text-title-large,
  .text-title-medium,
  .text-heading-small {
    color: var(--bh-text) !important;
  }

  h2 .icon,
  .container-header .icon,
  [class*="sort-header"] .icon {
    color: var(--bh-accent) !important;
  }

  ::selection { background: var(--bh-accent); color: #0a1024; }
}
